FONTS = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600&family=Onest:wght@400;500;600&family=Unbounded:wght@500;600&display=swap">'


def contact_buttons(cls=""):
    out = []
    if CONTACT["wa"]:
        out.append(f'<a class="btn {cls}" href="https://wa.me/{CONTACT["wa"]}" target="_blank" rel="noopener">Написать в WhatsApp</a>')
    if CONTACT["tg"]:
        out.append(f'<a class="btn ghost {cls}" href="https://t.me/{CONTACT["tg"]}" target="_blank" rel="noopener">Telegram</a>')
    return "".join(out) or '<span class="note">Контакты появятся здесь</span>'


def page(title, desc, body, root=""):
    return f'''<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{html.escape(title)}</title>
<meta name="description" content="{html.escape(desc)}">
{FONTS}
<link rel="stylesheet" href="{root}styles.css">
</head>
<body>
<header class="top"><div class="wrap">
  <a class="brand" href="{root}index.html">{BRAND}<i>.</i></a>
  <nav class="nav"><a href="{root}index.html#calc">Калькулятор</a><a href="{root}index.html#sites">Сайты</a><a href="{root}index.html#dashboards">Дашборды и системы</a><a href="{root}index.html#contacts">Контакты</a></nav>
  <a class="btn small" href="{root}index.html#contacts">Обсудить проект</a>
</div></header>
{body}
<footer><div class="wrap">{BRAND} · сайты, дашборды и ИИ-ассистенты для бизнеса. В демо-дашбордах все цифры и имена вымышлены.</div></footer>
<script src="{root}demo.js"></script>
</body>
</html>
'''


