# ---------------------------------------------------------------- pieces
def frame(s, root=""):
    imgs = ""
    for i, n in enumerate(s["frames"]):
        lazy = "" if i == 0 else 'loading="lazy" '
        imgs += f'<img src="{root}assets/shots/{s["key"]}-{n}.jpg" alt="{html.escape(s["title"])}, экран {i + 1}" {lazy}width="1440" height="900">'
    host = s["url"].split("//")[1].strip("/")
    return f'<div class="frame"><div class="frame-bar"><i></i><i></i><i></i><span>{host}</span></div><div class="slides">{imgs}</div><div class="dots"></div></div>'


def site_card(s):
    pts = "".join(f"<li>{p}</li>" for p in s["points"])
    return f'''<article class="case">
  {frame(s)}
  <div><span class="tag">{s["tag"]}</span><h3>{s["title"]}</h3><p>{s["lead"]}</p><ul>{pts}</ul>
  <div class="links"><a class="btn small" href="cases/{s["slug"]}.html">Как мы это делали →</a><a class="btn ghost small" href="{s["url"]}" target="_blank" rel="noopener">Открыть сайт ↗</a></div></div>
</article>'''


def dash_card(c):
    bars = "".join(f'<i style="height:{v}%"></i>' for v in c["bars"])
    go = "Открыть шаблон →" if c.get("template") else "Разбор и демо →"
    return f'<a class="card" href="cases/{c["slug"]}.html"><div class="mini" aria-hidden="true">{bars}</div><span class="tag plain">{c["tag"]}</span><h3>{c["title"]}</h3><p>{c["short"]}</p><span class="go">{go}</span></a>'


def story_blocks(c):
    out = []
    if c.get("story"):
        paras = "".join(f"<p>{p}</p>" for p in c["story"])
        out.append(f'<section class="tight"><h2>{c.get("story_h", "С чем пришли")}</h2><div class="story">{paras}</div></section>')
    if c.get("tasks"):
        items = "".join(f"<li>{t}</li>" for t in c["tasks"])
        out.append(f'<section class="tight"><h2>Что нужно было решить</h2><ul class="tasks">{items}</ul></section>')
    if c.get("brief"):
        brief = "".join(f"<div><h3>{h}</h3>{t if t.startswith('<') else '<p>' + t + '</p>'}</div>" for h, t in c["brief"])
        out.append(f'<section class="tight"><h2>Что это</h2><div class="brief">{brief}</div></section>')
    if c.get("decisions"):
        rows = "".join(f'<div class="decision"><h3>{h}</h3><p>{t}</p></div>' for h, t in c["decisions"])
        out.append(f'<section class="tight"><h2>{c.get("decisions_h", "Что сделали и почему")}</h2><div class="decisions">{rows}</div></section>')
    if c.get("status"):
        out.append(f'<section class="tight"><h2>Что в итоге</h2><div class="story"><p>{c["status"]}</p></div></section>')
    return "\n  ".join(out)


def cta(title, text):
    return f'<section><div class="cta"><h2>{title}</h2><p>{text}</p><div class="hero-actions">{contact_buttons()}</div></div></section>'


def site_page(s):
    return f'''<main><div class="wrap">
  <a class="crumb" href="../index.html#sites">← Все сайты</a>
  <div class="case-hero"><span class="tag">{s["tag"]}</span><h1 style="margin-top:14px">{s["h1"]}</h1><p class="lede">{s["lede"]}</p>
  <div class="hero-actions"><a class="btn ghost" href="{s["url"]}" target="_blank" rel="noopener">Открыть сайт ↗</a></div></div>
  <div class="frame-wide">{frame(s, "../")}</div>
  {story_blocks(s)}
  {cta("Хотите так же разобрать ваш сайт?", "Десять минут по видео: откроем ваш сайт или карточку в 2ГИС и покажем, где теряются заявки и что с этим сделать.")}
</div></main>'''


def dash_page(c):
    demo_note = "Это шаблон: переключайте фильтры. Все цифры и названия вымышлены." if c.get("template") else "Рабочая версия закрыта, поэтому здесь демо. Переключайте фильтры. Все цифры и имена вымышлены."
    return f'''<main><div class="wrap">
  <a class="crumb" href="../index.html#dashboards">← Все дашборды и системы</a>
  <div class="case-hero"><span class="tag">{c["tag"]}</span><h1 style="margin-top:14px">{c["h1"]}</h1><p class="lede">{c["lede"]}</p></div>
  <section class="tight"><div class="sec-head"><h2>Демо</h2><p>{demo_note}</p></div><div class="demo" data-demo="{c["demo"]}"></div></section>
  {story_blocks(c)}
  {cta("Нужен такой же по вашим данным?", "Расскажите, какие цифры вы сейчас собираете руками. Покажем, как это будет выглядеть на вашем примере.")}
</div></main>'''


